import java.io.BufferedReader;
import java.io.InputStreamReader;

public class VulnerableApp {
    public static void main(String[] args) {
        // Získání vstupu od uživatele (např. z HTTP požadavku)
        String userInput = "ls -l /"; // Předpokládejme, že toto je vstup od uživatele

        // Nesprávné použití: Spuštění příkazu z neověřeného vstupu
        try {
            // Toto je zranitelný kód, protože umožňuje externí procesy
            // provádět operace na systému.
            Process process = Runtime.getRuntime().exec(userInput);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```
